// PATCH(library): SeatWifi WiFi prediction (no auth, public JSON API at
// https://seatwifi.com). Not generated by Printing Press — seatwifi has no
// OpenAPI spec imported into flight-goat; this is a hand-written backend
// beside Google Flights, Kayak, Soar, and Seats.aero. See
// internal/seatwifi/seatwifi.go and the patch record in
// .printing-press-patches/seatwifi-wifi-source.json.

package cli

import (
	"context"
	"fmt"
	"net/url"
	"sort"
	"strings"
	"text/tabwriter"
	"unicode/utf8"

	"github.com/mvanhorn/printing-press-library/library/travel/flight-goat/internal/seatwifi"

	"github.com/spf13/cobra"
)

// newWifiCmd is the parent `wifi` group for SeatWifi read-only queries.
// Every subcommand is public (no API key) and hits https://seatwifi.com.
func newWifiCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "wifi",
		Short: "In-flight WiFi predictions via SeatWifi (no API key required)",
		Long: `SeatWifi in-flight WiFi predictions (https://seatwifi.com).

All subcommands hit SeatWifi's public JSON API — no API key required.
  wifi flight <flightNumber>   predicted provider / Starlink likelihood
  wifi airline <IATA>          fleet providers + notes for one airline
  wifi airlines                every tracked airline
  wifi rollouts [IATA]         Starlink rollout status
  wifi speed <flightNumber>    crowdsourced Mbps / latency for a flight
  wifi airline-speed <IATA>    crowdsourced Mbps / latency for an airline
  wifi search <query>          find airlines / flights / providers`,
		Example: `  # Predicted WiFi on a specific flight
  flight-goat-pp-cli wifi flight UA1234

  # Airline fleet + Starlink rollout
  flight-goat-pp-cli wifi airline AS
  flight-goat-pp-cli wifi rollouts UA

  # JSON for agents
  flight-goat-pp-cli wifi search starlink --agent`,
		Annotations: map[string]string{"mcp:read-only": "true"},
	}
	cmd.AddCommand(newWifiFlightCmd(flags))
	cmd.AddCommand(newWifiAirlineCmd(flags))
	cmd.AddCommand(newWifiAirlinesCmd(flags))
	cmd.AddCommand(newWifiRolloutsCmd(flags))
	cmd.AddCommand(newWifiSpeedCmd(flags))
	cmd.AddCommand(newWifiAirlineSpeedCmd(flags))
	cmd.AddCommand(newWifiSearchCmd(flags))
	return cmd
}

func newWifiFlightCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "flight <flightNumber>",
		Short: "WiFi provider for a flight number (e.g. UA1234)",
		Long: `SeatWifi flight WiFi prediction: GET /api/v1/flights/:flightNumber

Returns the predicted WiFi provider, confidence, aircraft type, tail when
known, Starlink likelihood, and a human details string.`,
		Annotations: map[string]string{"mcp:read-only": "true"},
		Args:        cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			flight := strings.ToUpper(strings.TrimSpace(args[0]))
			if flight == "" {
				return fmt.Errorf("flight number required")
			}
			c := seatwifi.NewClient()
			if flags.dryRun {
				return printWifiDryRun(cmd, flags, "seatwifi.GetFlight("+flight+")", c.BaseURL+"/api/v1/flights/"+url.PathEscape(flight))
			}
			ctx, cancel := wifiCtx(cmd, flags)
			defer cancel()
			res, err := c.GetFlight(ctx, flight)
			if err != nil {
				return err
			}
			if wantJSON(cmd, flags) {
				return printJSONFiltered(cmd.OutOrStdout(), res, flags)
			}
			return printWifiFlightHuman(cmd, res)
		},
	}
}

