func newWifiAirlinesCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:         "airlines",
		Short:       "All tracked airlines and their WiFi providers",
		Long:        `SeatWifi airlines list: GET /api/airlines — every tracked airline with provider + fleet info.`,
		Annotations: map[string]string{"mcp:read-only": "true"},
		Args:        cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			c := seatwifi.NewClient()
			if flags.dryRun {
				return printWifiDryRun(cmd, flags, "seatwifi.ListAirlines()", c.BaseURL+"/api/airlines")
			}
			ctx, cancel := wifiCtx(cmd, flags)
			defer cancel()
			list, err := c.ListAirlines(ctx)
			if err != nil {
				return err
			}
			if wantJSON(cmd, flags) {
				return printJSONFiltered(cmd.OutOrStdout(), list, flags)
			}
			fmt.Fprintf(cmd.ErrOrStderr(), "%d airlines (seatwifi)\n", len(list))
			tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
			fmt.Fprintln(tw, "CODE\tNAME\tPROVIDERS\tUPDATED")
			for _, a := range list {
				fmt.Fprintf(tw, "%s\t%s\t%s\t%s\n", humanText(a.Code), humanText(a.Name), humanText(strings.Join(a.WifiProvider, ",")), humanText(a.LastUpdated))
			}
			return tw.Flush()
		},
	}
}

func newWifiRolloutsCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "rollouts [IATA code]",
		Short: "Starlink rollout status — all airlines or one airline",
		Long: `SeatWifi Starlink rollouts: GET /api/rollouts or /api/rollouts/:code

Without an airline code, returns totals + byAirline map. With a code
(e.g. UA, AA), returns that airline's fleet rollout entries with status
(active/in_progress/planned/announced) and expected completion.`,
		Annotations: map[string]string{"mcp:read-only": "true"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			code := ""
			if len(args) == 1 {
				code = strings.ToUpper(strings.TrimSpace(args[0]))
			}
			c := seatwifi.NewClient()
			path := "/api/rollouts"
			if code != "" {
				path += "/" + url.PathEscape(code)
			}
			if flags.dryRun {
				return printWifiDryRun(cmd, flags, "seatwifi.GetRollouts("+code+")", c.BaseURL+path)
			}
			ctx, cancel := wifiCtx(cmd, flags)
			defer cancel()
			if code == "" {
				res, err := c.GetRollouts(ctx)
				if err != nil {
					return err
				}
				if wantJSON(cmd, flags) {
					return printJSONFiltered(cmd.OutOrStdout(), res, flags)
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "%d airlines, %d rollouts\n", res.TotalAirlines, res.TotalRollouts)
				tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
				fmt.Fprintln(tw, "AIRLINE	AIRCRAFT	STATUS	FLEET%	COMPLETION")
				codes := make([]string, 0, len(res.ByAirline))
				for ac := range res.ByAirline {
					codes = append(codes, ac)
				}
				sort.Strings(codes)
				for _, ac := range codes {
					for _, r := range res.ByAirline[ac] {
						fmt.Fprintf(tw, "%s	%s	%s	%s	%s\n", humanText(ac), humanText(r.AircraftType), humanText(r.Status), rolloutPct(r), humanText(rolloutDone(r)))
					}
				}
				return tw.Flush()
			}
			res, err := c.GetAirlineRollouts(ctx, code)
			if err != nil {
				return err
			}
			if wantJSON(cmd, flags) {
				return printJSONFiltered(cmd.OutOrStdout(), res, flags)
			}
			return printWifiAirlineRolloutsHuman(cmd, res)
		},
	}
}

